import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"ADR-0058: Stable transcript reflow and scroll ownership","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0058-stable-transcript-reflow.md","filePath":"adrs/0058-stable-transcript-reflow.md","lastUpdated":1789092097000}`),u={name:`adrs/0058-stable-transcript-reflow.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[3]||=a(`<h1 id="adr-0058-stable-transcript-reflow-and-scroll-ownership" tabindex="-1">ADR-0058: Stable transcript reflow and scroll ownership <a class="header-anchor" href="#adr-0058-stable-transcript-reflow-and-scroll-ownership" aria-label="Permalink to “ADR-0058: Stable transcript reflow and scroll ownership”">​</a></h1><p>Status: Accepted · 2026-09-07 · Refines ADRs 0053, 0056 and 0057.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The user reported chat content disappearing during font resizing and scrolling. A native regression exposed a stack-overflow crash in observable font setters that assigned to themselves unconditionally. The transcript also fed estimated lazy-stack heights into immediate scroll commands and animated row placement.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Use a fully measured <code>VStack</code> containing at most 40 messages, with the existing bounded Markdown cache. Native lazy-stack height estimates remained unstable under large font/width changes, and the native list alternative failed the selection/reflow regressions. A bounded measured window trades implicit whole-history scrolling for predictable geometry and bounded rich-view work.</p>`,6),c(`p`,null,[l[1]||=i(`Earlier and Later controls move by 20 messages with an overlapping window, preserving the current edge as a message-ID scroll target. Latest and a new send return to the newest window. All messages remain in the model and database; model `,-1),r(m,{term:`context-window`},{default:n(()=>[...l[0]||=[i(`context`,-1)]]),_:1}),l[2]||=i(` and generation ownership do not use this display range. Loading/evicting model history remains separate work.`,-1)]),l[4]||=a(`<p>Each message contributes one stable, vertically self-sizing child. Row insertion fades and offsets are removed. Native scroll-position binding preserves reading identity; native size-change anchors handle font, width and prepared-content reflow. Estimated content heights no longer drive explicit scrolling.</p><p>A bottom sentinel tracks whether the reader has reached the end. Reader gestures suspend following through deceleration; ending at the bottom resumes it. New sends resume following. Stream-driven commands retain their 15 Hz upper bound and are always deferred out of the current layout frame. Disappearance and reader gestures cancel pending commands.</p><p>Font setters assign a normalized value only when it differs, then persist the canonical value. This bounds observable setter reentry while preserving existing preference keys and valid ranges.</p><h2 id="consequences-and-validation" tabindex="-1">Consequences and validation <a class="header-anchor" href="#consequences-and-validation" aria-label="Permalink to “Consequences and validation”">​</a></h2><p>No storage, network authority, dependency or cache policy changes. Visibility observations stay outside observable view state; resuming following is deferred to avoid layout feedback. Long-history paging and large-code rendering remain PERF-01 and PERF-04.</p><p>Native regressions cover long/short chat selection, 80 messages across five width/font combinations and five native wheel movements, and scroll-wheel events followed by streaming and reflow. Font tests cover repeated, fractional, out-of-range and non-finite assignments and persistence. Visual inspection uses the complete hosting view, not its transparent clipping layer.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li><a href="https://developer.apple.com/documentation/swiftui/creating-performant-scrollable-stacks" target="_blank" rel="noreferrer">Apple: creating performant scrollable stacks</a></li><li><a href="https://developer.apple.com/documentation/swiftui/view/scrolltargetlayout(isenabled:)" target="_blank" rel="noreferrer">Apple: scroll target layouts</a></li><li><a href="https://developer.apple.com/documentation/swiftui/view/defaultscrollanchor(_:for:)" target="_blank" rel="noreferrer">Apple: default scroll anchors by role</a></li></ul>`,8)])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};